unsigned char* digest;
utils::basic_hash(msg.c_str(), msg.length(), &digest);

unsigned long hash = 0;
for (int i = 0; i < MD5_DIGEST_LENGTH; i++) {
    hash = (hash * kBase) + digest[i];
}
hash %= kModulo;

delete[] digest;
return static_cast<float>(hash) / kModulo;

